    const mk=(body)=>`<prop type="doc" kind="vlog" from="Ada" sol="4208" delay="14 min 31 s" margin="`+A+` days" title="ADA OKAFOR · ARES STATION · SOL 4208 · LOG 56 · ONE WAY 14 MIN 31 S">`+body+`</prop>`;
